// === Tab: mySketch ===
let rads=[]
let suncolors=["#df9a57","#fc7a57","#fcd757","#eefc57","#5e5b52"]
let timer=0
let wet=[]
let colors=["#13293d","#006494","#247ba0","#1b98e0","#e8f1f2"]
let size

function setup() {
  createCanvas(800, 800);
  angleMode(DEGREES)
}

function draw() {
  size=width/30
  brickSize=20
  colorer=0
  clear()
 background(255);

 if(timer==5){  
  for(let i=0; i<360; i+=10){
  rads.push(new rad(125, 125, i))
  }
    timer=0
  }
  timer+=1

  for(let i = rads.length-1 ;i>=0;i--){
    rads[i].update();
    rads[i].display();
    }  

  for(let i=width*.75; i<width*1.25; i+=size+1){
    wet.push(new water(i))
  }

for(let i = wet.length-1 ;i>=0;i--){
    wet[i].update();
    wet[i].display();
    }  
}

class water{
  constructor(x){
    this.pos= createVector(x, -50)
    this.acc= createVector(0, 0)
    this.vel= createVector(0, 0)
    this.spray= createVector(random(-4, 4), 0)
    this.curve1=random(-20, 20)
    this.curve2=random(-20, 20)
    this.color=color (random(colors))
  }
  update(){
    //river
    this.acc.set(0, 0)
    this.vel.limit(3, 4)
    if(this.pos.y<height/6){
      this.acc.add(-0.3, 0.2)
    }
    //fall
    if(this.pos.y>=height/5){
      this.acc.add(0, 0.1)
    }

  //move  
  this.vel.add(this.acc)
  this.pos.add(this.vel)

  //cut
    if (this.pos.y> height) {
      let index = wet.indexOf(this);
      wet.splice(index, 1);
    }

  }

  display(){
    noStroke()
    push()
    translate(this.pos.x, this.pos.y)
    let r=this.vel.heading()
    rotate(r)
    fill(this.color)
    this.color.setAlpha(50)
    noStroke()
    strokeWeight(20)
    strokeCap(PROJECT)
    rect(0, 0, size)
    pop()

  }
}



class rad {
  constructor(x, y, r){
    this.rotation=r
    this.x=x
    this.y=y
    this.r=r
    this.moved=0
    this.lifespan=100
    this.color=color (random(suncolors))
  }
  update(){
   this.moved+=1
   this.lifespan-=1

    if (this.lifespan < 0) {
      var index = rads.indexOf(this);
      rads.splice(index, 1);
    }
  }
  display(){
    push()
    translate(this.x, this.y)
    stroke(this.color)
    this.color.setAlpha(80)
    strokeWeight(10)
    strokeCap(PROJECT)
    rotate(this.r)
    line(0,this.moved, 0, this.moved-30)
    pop()

  }
}

